import {lessons} from './course.mjs';
import {parseWorkbookSheets,aggregate,groupRows,filteredRows,scenario,csvText} from './analytics.mjs';
import {esc,num,usd} from './charts.mjs';
import {views} from './views.mjs';
const main=document.querySelector('main'),storageKey='air-france-course-notes-v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{}
if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};
for(const l of lessons){const n=saved[l.id];if(!n||typeof n!=='object'||Array.isArray(n))delete saved[l.id];else {n.text=typeof n.text==='string'?n.text:'';n.complete=n.complete===true}}
const state={data:null,notes:saved,tab:'task',publisher:'',query:'',minClicks:0,page:0,tablePage:0,budgets:{},cap:null,cpcChange:0,cvrChange:0,importing:false};
const localAvailable=!!document.querySelector('meta[name="local-case"]');
const view=views(state,localAvailable),routes=new Set(['overview','brief','q1','q2','q3','q4','data','notes']);
let rawBytes=null,fileName='',toastTimer;
const route=()=>routes.has(location.hash.slice(1))?location.hash.slice(1):'overview';
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state.notes));return true}catch{toast('浏览器无法保存，请及时导出作答。');return false}}
function download(content,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function updateScenario(){const el=document.querySelector('#scenario-results');if(!el)return;try{const r=scenario(groupRows(state.data.rows,'publisher'),state.budgets,{cpcChange:state.cpcChange,cvrChange:state.cvrChange,cap:state.cap});el.innerHTML=`<div class="result-list">${[['已分配预算',usd(r.budget,2)],['预订量（情景期望值）',num(r.bookings,1)],['销售收入（情景）',usd(r.revenue,2)],['广告费后余额（非利润）',usd(r.balance,2)]].map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>${r.overCap?`<div class="notice"><p>超过预算上限 ${usd(r.budget-state.cap,2)}，请调整后再保存。</p></div>`:''}${!r.valid?'<div class="notice"><p>部分渠道缺少可用历史效率，无法估算全部结果。请将对应预算设为零或补充依据。</p></div>':''}<button class="button primary" data-action="save-scenario" ${r.overCap||!r.valid?'disabled':''}>把情景保存到本题记录</button><p class="small" style="margin-top:12px">保存预算、假设、结果与数据指纹，方便复盘追溯。</p>`}catch(e){el.innerHTML=`<div class="notice"><p>${esc(e.message)}</p></div>`}}
function render(){const r=route();document.querySelectorAll('[data-route]').forEach(a=>{const active=a.dataset.route===r;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('#breadcrumb').textContent=({overview:'课程总览',brief:'案例简报',data:'数据与口径',notes:'我的分析记录'}[r]||lessons.find(l=>l.id===r)?.title);const d=document.querySelector('#data-status');d.textContent=state.data?`${num(state.data.rows.length)} 条数据已载入`:'数据待导入';d.classList.toggle('ready',!!state.data);main.innerHTML=r.startsWith('q')?view.lesson(r):view[r]();if(r==='overview'){const completed=lessons.filter(l=>state.notes[l.id]?.complete).length;const stats=main.querySelectorAll('.stat-line');if(stats[1])stats[1].innerHTML=`<span>学习进度</span><strong>${completed} / 4 道</strong>`;main.querySelectorAll('.lesson').forEach((el,i)=>{if(state.notes[lessons[i].id]?.complete)el.querySelector('.lesson-time').textContent='✓ 已标记完成'});if(state.data){const card=main.querySelector('.aside-card');card.querySelector('h3').textContent='数据已就绪';card.querySelector('.pill').textContent=`${num(state.data.rows.length)} 条主表记录`;card.querySelector('.pill').classList.add('ready');card.querySelector('p').textContent=state.data.meta.sourceKind==='public-course-mirror'?'公开课程镜像已载入；分析以当前文件为准，后续需核对官方版本。':'当前文件已载入，点击进入第一题。';const link=card.querySelector('.button');link.href='#q1';link.textContent='进入第一道题 ↗'}}if(r==='q4'&&state.tab==='analysis'&&state.data)updateScenario()}
function applyDataset(data,bytes,name){state.data=data;rawBytes=bytes;fileName=name;state.publisher='';state.query='';state.minClicks=0;state.page=0;state.tablePage=0;state.budgets={};render();toast(`已载入 ${num(data.rows.length)} 条记录。`)}
async function loadParser(){if(globalThis.XLSX)return globalThis.XLSX;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/vendor/xlsx.full.min.js';s.onload=resolve;s.onerror=()=>reject(Error('Excel 读取组件不可用，请检查网站文件。'));document.head.append(s)});if(!globalThis.XLSX)throw Error('Excel 读取组件未初始化');return globalThis.XLSX}
async function importFile(file){if(state.importing)return;if(file.size>20*1024*1024){toast('文件超过 20 MB，请使用课程配套表格。');return}state.importing=true;const message=document.querySelector('#import-message');if(message){message.textContent='正在检查表头与数据口径…';message.classList.remove('error')}try{const XLSX=await loadParser(),bytes=await file.arrayBuffer(),wb=XLSX.read(bytes,{type:'array'});const sheets=wb.SheetNames.map(name=>({name,startRow:wb.Sheets[name]['!ref']?XLSX.utils.decode_range(wb.Sheets[name]['!ref']).s.r:0,matrix:XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:null})}));const hash=crypto.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(n=>n.toString(16).padStart(2,'0')).join(''):null;const data=parseWorkbookSheets(sheets,{filename:file.name,sha256:hash,sourceKind:'local-import',authority:'用户本地导入；真实性未自动认证',retrievedAt:new Date().toISOString()});applyDataset(data,bytes,file.name)}catch(e){if(message){message.textContent=e.message;message.classList.add('error')}toast('导入失败，原有数据保持不变。')}finally{state.importing=false}}
async function loadLocal(){if(!localAvailable||state.importing)return;state.importing=true;try{const response=await fetch('/__local/inspected-data.json');if(!response.ok)throw Error('本地数据尚未就绪');const d=await response.json(),file=await fetch('/__local/air-france-mirror.xls');if(!file.ok)throw Error('原始工作簿不可用');applyDataset(d,await file.arrayBuffer(),'air-france-mirror.xls')}catch(e){toast(e.message)}finally{state.importing=false}}
function exportNotes(){let text='# Air France 广告经营分析实战 · 我的作答\n\n导出时间：'+new Date().toLocaleString('zh-CN')+'\n\n当前文件：'+(state.data?.meta.filename||'未导入')+'\n\n';for(const l of lessons){const n=state.notes[l.id]||{};text+=`## ${l.n} ${l.title}\n\n状态：${n.complete?'自行标记完成':'待完成'}\n\n${n.text||'（未填写）'}\n\n`;if(n.datasetHash)text+='作答数据 SHA-256：'+n.datasetHash+'\n\n';if(n.scenario)text+='### 已保存的预算情景\n\n```json\n'+JSON.stringify(n.scenario,null,2)+'\n```\n\n'}download(text,'Air-France-我的分析记录.md','text/markdown;charset=utf-8')}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='tab'){state.tab=b.dataset.tab;render();document.querySelector('#tab-'+state.tab)?.focus()}if(a==='load-local')await loadLocal();if(a==='download-original'&&rawBytes)download(new Blob([rawBytes]),fileName);if(a==='preview-page'||a==='keywords-page'){state[a==='preview-page'?'tablePage':'page']+=Number(b.dataset.delta);const y=window.scrollY;render();window.scrollTo(0,y)}if(a==='complete'){const id=b.dataset.id,n=state.notes[id]||{};if(!n.text?.trim()){toast('先写下你的判断，再标记完成。');return}state.notes[id]={...n,complete:!n.complete};save();const y=window.scrollY;render();window.scrollTo(0,y);toast(state.notes[id].complete?'已标记完成，可随时修改。':'已撤回完成标记。')}if(a==='apply-filters'){const min=Number(document.querySelector('#min-clicks').value);if(!Number.isFinite(min)||min<0||!Number.isInteger(min)){toast('最少点击应为非负整数。');return}state.publisher=document.querySelector('#publisher-filter').value;state.query=document.querySelector('#keyword-query').value;state.minClicks=min;state.page=0;render()}if(a==='check-cpa'){const text=document.querySelector('#cpa-check').value,n=Number(text),expected=aggregate(state.data.rows).cpa;document.querySelector('#cpa-feedback').textContent=text!==''&&Number.isFinite(n)&&expected!==null&&Math.abs(n-expected)<=.015?'✓ 计算一致。请继续解释指标的经营意义。':`检查总花费 / 总预订量，当前结果为 ${usd(expected,2)}。`}if(a==='reset-budget'){state.budgets={};render();toast('已恢复历史花费，假设回到历史水平。')}if(a==='save-scenario'){try{const r=scenario(groupRows(state.data.rows,'publisher'),state.budgets,{cpcChange:state.cpcChange,cvrChange:state.cvrChange,cap:state.cap});if(r.overCap||!r.valid)return;state.notes.q4={...state.notes.q4,scenario:{savedAt:new Date().toISOString(),datasetHash:state.data.meta.sha256,cap:state.cap,cpcChange:state.cpcChange,cvrChange:state.cvrChange,...r},updatedAt:new Date().toISOString()};save();toast('情景已保存，可在导出的作答中查看。')}catch(e){toast(e.message)}}if(a==='export-notes')exportNotes();if(a==='export-summary'){const groups=groupRows(state.data.rows,'publisher');download(csvText(['Publisher','Cost','Clicks','Bookings','Revenue','CPC','CVR','CPA','ROAS'],groups.map(g=>[g.name,g.cost,g.clicks,g.bookings,g.revenue,g.cpc,g.cvr,g.cpa,g.roas])),'Air-France-渠道汇总.csv','text/csv;charset=utf-8')}if(a==='export-keywords'){const rows=filteredRows(state.data.rows,{publisher:state.publisher,query:state.query,minClicks:state.minClicks});download(csvText(['Source Sheet','Source Row','Publisher','Campaign','Keyword','Match Type','Bid Strategy','Clicks','Cost','Bookings','Revenue'],rows.map(r=>[r.sourceSheet,r.sourceRow,r.publisher,r.campaign,r.keyword,r.matchType,r.bidStrategy,r.clicks,r.cost,r.bookings,r.revenue])),'Air-France-关键词筛选.csv','text/csv;charset=utf-8')}});
document.addEventListener('change',e=>{if(e.target.id==='case-file'&&e.target.files[0])importFile(e.target.files[0])});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.answer){const id=el.dataset.answer;state.notes[id]={...state.notes[id],text:el.value,complete:false,updatedAt:new Date().toISOString(),datasetHash:state.data?.meta.sha256||null};const ok=save(),s=document.querySelector('#save-status');if(s)s.textContent=ok?'已保存到此浏览器':'保存失败，请导出作答';const b=document.querySelector(`[data-action="complete"][data-id="${id}"]`);if(b)b.textContent='标记本题完成'}if(el.dataset.budget){state.budgets[el.dataset.budget]=el.value===''?NaN:Number(el.value);updateScenario()}if(el.id==='budget-cap'){state.cap=el.value===''?NaN:Number(el.value);updateScenario()}if(el.id==='cpc-change'||el.id==='cvr-change'){state[el.id==='cpc-change'?'cpcChange':'cvrChange']=Number(el.value);document.querySelector('#'+el.id+'-label').textContent=el.value+'%';updateScenario()}});
document.addEventListener('keydown',e=>{if(e.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const t=['task','analysis','reference'];let n=t.indexOf(state.tab);n=e.key==='Home'?0:e.key==='End'?2:(n+(e.key==='ArrowRight'?1:2))%3;state.tab=t[n];render();document.querySelector('#tab-'+state.tab)?.focus()}});
window.addEventListener('hashchange',()=>{state.tab='task';render();window.scrollTo(0,0);main.focus({preventScroll:true})});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'read_course_state',title:'读取课程状态',description:'读取当前课程页、数据状态和自标记进度，不返回作答或原始记录。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('无需参数');return{route:route(),view:state.tab,rows:state.data?.rows.length||0,sourceKind:state.data?.meta.sourceKind||null,completed:lessons.filter(l=>state.notes[l.id]?.complete).map(l=>l.id)}}},{name:'navigate_course',title:'打开课程题目',description:'切换课程页或题目视图，不导入数据、不修改或提交作答。',inputSchema:{type:'object',properties:{route:{type:'string',enum:[...routes]},view:{type:'string',enum:['task','analysis','reference']}},required:['route'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!routes.has(input.route)||Object.keys(input).some(k=>!['route','view'].includes(k))||(input.view&&!['task','analysis','reference'].includes(input.view)))throw Error('无效的课程页或视图');history.replaceState(null,'','#'+input.route);state.tab=input.view||'task';render();window.scrollTo(0,0);return{route:route(),view:state.tab}}}];for(const tool of definitions){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
